update pages set contenu = '{"gabarit":"fiche","chapeau":"En août 2023, AKTID a confié à Migen le montage de son nouveau centre logistique, à Clermont-Ferrand. Six semaines de chantier en pleine période estivale, avec une date de livraison qui ne bougeait pas.","fiche":[],"contexte":"**Un montage qui glisse, c''est une mise en service qui glisse, et toute l''exploitation derrière.** La date de livraison, elle, ne se renégocie pas.\nLe projet a présenté d''importants défis pour les équipes engagées :\n**La période estivale** : Le moment le plus difficile de l''année pour réunir des monteurs disponibles.\n**Des délais impartis** : La livraison du centre logistique était bornée dans le calendrier.\n**Un montage lourd** : Les installations demandaient des moyens de levage en nombre.\n**Des obstacles en cours de route** : Plusieurs difficultés ont dû être franchies pendant le chantier.","intervention":"**Une équipe de montage complète** : 12 monteurs mécaniciens mobilisés sur le chantier, soit plus d''une dizaine d''intervenants en simultané.\n**Les moyens de levage sur place** : 8 engins de levage engagés pour le montage des installations.\n**Une équipe intégrée au client** : Les équipes Migen ont travaillé en lien direct avec celles d''AKTID, sur le même planning.\n**Un chantier calé sur la saison** : Le montage a été conduit pendant l''été, avec les contraintes de disponibilité que cela impose.\n**Un objectif unique** : Livrer le centre logistique dans les délais impartis, sans arbitrage sur la qualité du montage.","resultats":[]}'::jsonb where path = '/preuves/aktid-centre-logistique/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"AKTID"},{"libelle":"Site","valeur":"Nouveau centre logistique, Clermont-Ferrand"},{"libelle":"Période","valeur":"Chantier démarré en août 2023"},{"libelle":"Moyens humains","valeur":"12 monteurs mécaniciens"},{"libelle":"Moyens matériels","valeur":"8 engins de levage"},{"libelle":"Durée","valeur":"6 semaines de travaux"},{"libelle":"Nature des travaux","valeur":"Montage d''installations logistiques"}]'::jsonb) where path = '/preuves/aktid-centre-logistique/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Le site livré dans les temps","libelle":"Après environ six semaines de chantier, le centre logistique a été remis à la date prévue."},{"valeur":"Une réussite conjointe","libelle":"Le résultat tient à la collaboration étroite entre les équipes Migen et les équipes AKTID, malgré les défis rencontrés."}]'::jsonb) where path = '/preuves/aktid-centre-logistique/';
